from primitives import call

def submit(action, parameters):
    r = call(name="submit_capx_action", action=action, native_api=True, parameters=parameters)
    print(action, r.ok, r.output)
    if r.ok:
        return r.output
    return None

names = ["toolbox", "hammer", "screwdriver", "wrench", "pliers", "tape measure", "measuring tape", "saw", "drill"]
found = {}
for name in names:
    out = submit("get_object_pose", {"object_name": name, "return_bbox_extent": True})
    if out is not None:
        found[name] = out
print("FOUND", list(found.keys()))

